 rows.append([', '.join(f'{v:.2f}' for v in x['beam_y']),'/'.join(x['selection'][n+':beam'] for n in x['beam_names']),f"{x['steel_with_connections_lb']:,.0f}",f"{x['max_ratio']:.3f}",f"{x['max_vertical_in']:.3f}",'Meets' if x['feasible'] else 'Exceeds'])
